CREATE TABLE groupes_matieres (
    id    INTEGER PRIMARY KEY AUTOINCREMENT,
    nom   TEXT NOT NULL UNIQUE,
    ordre INTEGER NOT NULL                         -- ordre d'affichage sur le bulletin
);
INSERT INTO "groupes_matieres" VALUES(1,'Sciences et Technologies',1);
INSERT INTO "groupes_matieres" VALUES(2,'Langues et Littératures',2);
INSERT INTO "groupes_matieres" VALUES(3,'Développement personnel',3);
INSERT INTO "groupes_matieres" VALUES(4,'Sciences Humaines',4);
CREATE TABLE matieres (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    nom         TEXT NOT NULL UNIQUE,
    coefficient INTEGER NOT NULL CHECK (coefficient > 0),
    groupe_id   INTEGER NOT NULL REFERENCES groupes_matieres (id),
    ordre       INTEGER NOT NULL
);
